{
  "title": "Shared Todo — Weekend Trip",
  "body": "<div class="todo-app">
  <h2>Shared Todo List</h2>
  <p class="subtitle">Planning our weekend trip — add, tick off, or delete tasks.</p>
  <div class="todo-input-row">
    <input id="todo-input" type="text" placeholder="Add a new task…" />
    <button id="todo-add">Add</button>
  </div>
  <ul id="todo-list"></ul>
  <div class="todo-footer"><span id="todo-count"></span></div>
</div>",
  "css": ".todo-app { font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; max-width: 460px; margin: 0 auto; padding: 20px; background: #ffffff; border: 1px solid #e4e4e7; border-radius: 14px; box-shadow: 0 4px 14px rgba(0,0,0,0.06); }
.todo-app h2 { margin: 0 0 2px; font-size: 20px; color: #18181b; }
.subtitle { margin: 0 0 14px; font-size: 13px; color: #71717a; }
.todo-input-row { display: flex; gap: 8px; margin-bottom: 14px; }
#todo-input { flex: 1; padding: 9px 12px; font-size: 14px; border: 1px solid #d4d4d8; border-radius: 8px; outline: none; }
#todo-input:focus { border-color: #6366f1; box-shadow: 0 0 0 3px rgba(99,102,241,0.15); }
#todo-add { padding: 9px 16px; font-size: 14px; font-weight: 600; color: #ffffff; background: #6366f1; border: none; border-radius: 8px; cursor: pointer; }
#todo-add:hover { background: #4f46e5; }
#todo-list { list-style: none; margin: 0; padding: 0; }
.todo-item { display: flex; align-items: center; gap: 10px; padding: 10px 8px; border-bottom: 1px solid #f0f0f2; }
.todo-item input[type="checkbox"] { width: 17px; height: 17px; accent-color: #6366f1; cursor: pointer; flex-shrink: 0; }
.todo-text { flex: 1; font-size: 14px; color: #27272a; cursor: pointer; }
.todo-item.done .todo-text { text-decoration: line-through; color: #a1a1aa; }
.todo-delete { border: none; background: transparent; color: #a1a1aa; font-size: 18px; line-height: 1; cursor: pointer; padding: 2px 6px; border-radius: 6px; }
.todo-delete:hover { color: #ef4444; background: #fef2f2; }
.todo-empty { padding: 14px 8px; font-size: 13px; color: #a1a1aa; text-align: center; list-style: none; }
.todo-footer { margin-top: 12px; padding-top: 10px; border-top: 1px solid #f0f0f2; font-size: 13px; font-weight: 600; color: #52525b; }",
  "scripts": [
    "if (!state.todos) {
  state.todos = [
    { id: 1, text: "Pick a destination and dates for the weekend trip", done: false },
    { id: 2, text: "Book transport and a place to stay", done: false },
    { id: 3, text: "Check the forecast and write a packing list", done: false }
  ];
}
if (!state.nextId) {
  state.nextId = 4;
}

const listEl = root.querySelector("#todo-list");
const countEl = root.querySelector("#todo-count");
const inputEl = root.querySelector("#todo-input");
const addBtn = root.querySelector("#todo-add");

const render = () => {
  listEl.replaceChildren();
  state.todos.forEach((todo) => {
    const li = root.create("li");
    li.classList.add("todo-item");
    if (todo.done) {
      li.classList.add("done");
    }

    const box = root.create("input");
    box.setAttribute("type", "checkbox");
    box.checked = todo.done;
    box.addEventListener("change", () => {
      todo.done = !todo.done;
      render();
    });

    const label = root.create("span");
    label.classList.add("todo-text");
    label.textContent = todo.text;
    label.addEventListener("click", () => {
      todo.done = !todo.done;
      render();
    });

    const del = root.create("button");
    del.classList.add("todo-delete");
    del.setAttribute("title", "Delete");
    del.textContent = "\u00d7";
    del.addEventListener("click", () => {
      state.todos = state.todos.filter((t) => t.id !== todo.id);
      render();
    });

    li.append(box, label, del);
    listEl.append(li);
  });

  if (state.todos.length === 0) {
    const empty = root.create("li");
    empty.classList.add("todo-empty");
    empty.textContent = "All clear — add a task above.";
    listEl.append(empty);
  }

  const left = state.todos.filter((t) => !t.done).length;
  const total = state.todos.length;
  countEl.textContent = total === 0
    ? "Nothing left to do"
    : left + (left === 1 ? " item left" : " items left") + " \u00b7 " + total + " total";
};

const addTodo = () => {
  const text = (inputEl.value || "").trim();
  if (text.length === 0) {
    return;
  }
  state.todos.push({ id: state.nextId, text: text, done: false });
  state.nextId = state.nextId + 1;
  inputEl.value = "";
  render();
};

addBtn.addEventListener("click", addTodo);
inputEl.addEventListener("change", addTodo);

render();"
  ]
}
